const cards = [0, 1, 2, 3, 4, 5].map(i => root.querySelector('#c' + i));
const val = root.querySelector('#val');
const path = root.querySelector('#path');
const pathLen = path.getTotalLength();
path.style.strokeDasharray = pathLen;
path.style.strokeDashoffset = pathLen;

function frame(t, p, d) {
  const isSettled = p >= 0.55;

  // Line animation
  const ls = spr(t, 0.1, 0.8, 6);
  path.style.strokeDashoffset = isSettled ? 0 : pathLen * (1 - ls);

  cards.forEach((el, i) => {
    const delay = i * 0.45;
    const s = spr(t, delay, 0.9, 8);
    const actS = isSettled ? 1 : s;

    el.style.opacity = clamp(actS * 2);
    const ySlide = lerp(30, 0, E_OUT(clamp(actS)));
    const scale = lerp(0.94, 1, E_OUT(clamp(actS)));
    el.style.transform = `translateY(${ySlide}px) scale(${scale})`;

    // Tool counter on last card
    if (i === 5) {
      const countProgress = spr(t, delay + 0.2, 0.9, 5);
      const currentCount = Math.floor(lerp(0, 23, E_OUT(clamp(isSettled ? 1 : countProgress))));
      val.textContent = currentCount;
    }
  });

  if (isSettled) {
    path.style.strokeDashoffset = 0;
    val.textContent = "23";
    cards.forEach(el => {
      el.style.opacity = 1;
      el.style.transform = "translateY(0px) scale(1)";
    });
  }
}
